    def verify_drone_position_on_map(self):
        """Verify drone appears in correct position on map"""
        try:
            logger.info("🔍 Verifying drone position on map...")

            # Get drone marker position from map
            marker_data = self.driver.execute_script("""
                const map = document.getElementById('map')._leaflet;
                let droneMarker = null;
                let markerPosition = null;
                let mapCenter = null;

                // Find drone marker
                map.eachLayer(function(layer) {
                    if (layer.options && layer.options.title === 'Drone Position') {
                        droneMarker = layer;
                        markerPosition = layer.getLatLng();
                    }
                });

                mapCenter = map.getCenter();

                return {
                    markerFound: droneMarker !== null,
                    markerPosition: markerPosition ? {
                        lat: markerPosition.lat, 
                        lng: markerPosition.lng
                    } : null,
                    mapCenter: {
                        lat: mapCenter.lat,
                        lng: mapCenter.lng
                    },
                    mapZoom: map.getZoom()
                };
            """)

            # Verify marker exists
            if not marker_data["markerFound"]:
                logger.error("❌ Drone marker not found on map")
                return False

            # Verify position accuracy
            if marker_data["markerPosition"]:
                marker_lat = marker_data["markerPosition"]["lat"]
                marker_lng = marker_data["markerPosition"]["lng"]

                # Calculate distance between expected and actual position
                lat_diff = abs(marker_lat - self.drone_position["lat"])
                lng_diff = abs(marker_lng - self.drone_position["lon"])

                # Allow for small floating point differences (< 0.0001 degrees ≈ 10 meters)
                position_accurate = lat_diff < 0.0001 and lng_diff < 0.0001

                logger.info(f"Expected position: {self.drone_position['lat']:.6f}, {self.drone_position['lon']:.6f}")
                logger.info(f"Marker position: {marker_lat:.6f}, {marker_lng:.6f}")
                logger.info(f"Position accuracy: Lat diff: {lat_diff:.8f}, Lng diff: {lng_diff:.8f}")

