        timestamp = datetime.now().strftime("%Y%m%d_%H%M%S")
        report_path = f"/Users/peterburke/Documents/Code/WebGCS5/DRONE_LOCATION_MAP_DISPLAY_TEST_REPORT_{timestamp}.md"

