        logger.info(f"📄 Visual test report saved: {report_path}")
        return report_path

    def cleanup(self):
        """Cleanup resources"""
        try:
            if self.driver:
                self.driver.quit()
                logger.info("🧹 Browser session closed")

            if self.webserver_process:
                self.webserver_process.terminate()
